    if (node == null || node.left == null) {
        return node; // No rotation needed
    }

    TreeNode<T> newParent = node.left;
    node.left = newParent.right;
    newParent.right = node;

    node.parent = newParent;
    if (newParent.parent != null && newParent.parent.right == newParent) {
        newParent.parent.right = newParent;
    } else if (newParent.parent != null && newParent.parent.left == newParent) {
        newParent.parent.left = newParent;
