public static void addToClassPath(Vector<URL> cpV, String dir) {
    try (File f = new File(dir);
         FileInputStream fis = new FileInputStream(f);
         JarInputStream jis = new JarInputStream(fis);) {
        Enumeration<JarEntry> e = jis.entries();
        while (e.hasMoreElements()) {
            JarEntry je = e.nextElement();
            URL url = new URL("jar:" + file.toURI().toURL() + "!/" + je.getName());
            cpV.add(url);
        }
    } catch (Exception e) {
        e.printStackTrace();
    }
}

private static void addToClassPath(Vector<URL> cpV, String dir) {
    File directory = new File(dir);
    if (directory.exists() && directory.isDirectory()) {
        String[] files = directory.list();
        for (String file : files) {
            if (file.endsWith(".jar")) {
                try {
                    File jarFile = new File(dir + File.separator + file);
                    cpV.add(jarFile.toURI().toURL());
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
        }
    } else {
        System.err.println("Directory does not exist or is not a directory.");
    }
}

