        return ranges; // Handle invalid input or invalid range
    }
    ranges.add(new TimeRange(start, min(end, FETCH_DATA_DURATION)));
    ranges.add(new TimeRange(max(start, FETCH_DATA_DURATION), end));
    return ranges;
}

private List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    if (end - start < FETCH_DATA_DURATION) {
        timeRanges.add(new TimeRange(start, end));
    } else {
        // Split the range into smaller time ranges
        int rangeSize = (int) (end - start) / FETCH_DATA_DURATION;
        for (int i = 0; i < (end - start) / rangeSize; i++) {
            timeRanges.add(new TimeRange(start + i * rangeSize, start + (i + 1) * rangeSize));
        }
        if ((end - start) % rangeSize > 0) {
            timeRanges.add(new TimeRange(start + (end - start) / rangeSize * rangeSize, end));
        }
    }
    return timeRanges;
}

