public static int computeUTF8Size(CharSequence str, int index, int len) {
    int UTF8_SIZE = 0;
    for (int i = index; i < index + len; i++) {
        int value = str.charAt(i);
        if ((value & 0xF8) == 0xF0) {
            UTF8_SIZE += 4; // Four bytes
        } else if ((value & 0xE0) == 0xE0) {
            UTF8_SIZE += 3; // Three bytes
        } else if ((value & 0xC0) == 0xC0) {
            UTF8_SIZE += 2; // Two bytes
        } else {
            UTF8_SIZE++; // One byte
        }
    }
    return UTF8_SIZE;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch >= 32 && ch <= 126) {
            size++;
        } else if (ch > 126) {
            switch (ch) {
                case 127:
                    size += 2;
                    break;
                case 128:
                    size += 4;
                    break;
