public static int computeUTF8Size(CharSequence str, final int index, final int len) {
    if (str == null || len <= 0 || index >= str.length()) {
        return 0; // Invalid input
    }
    int size = 0;
    boolean highSurrogate = false;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if ((c & 0xE0) == 0xC0) {
            continue; // Not a multi-byte sequence
        } else if ((c & 0xE0) == 0xF0) {
            if (i + 1 > index + len - 1) {
                return 0; // Invalid input
            }
            highSurrogate = true;
            c = (char) (c & 0x1F);
        }
        if (highSurrogate) {
            // Multi-byte sequence with a high surrogate
            if ((c & 0xFC) != 0x80) {
                return 0; // Invalid input
            }
            size += 3;
        } else {
            // Regular single-byte sequence
            size += 1;
        }
    }
    return size;
}

