    if (str == null || str.isEmpty()) {
        throw new IllegalArgumentException("Input string cannot be null or empty");
    }
    for (int i = 0; i < str.length(); i++) {
        int c = str.charAt(i);
        if (Character.isBom(c)) {
            continue; // Skip BOM
        }
        if (c == '\n') {
            // Convert LF to CRLF
            lb.append((byte) '\r');
            lb.append((byte) '\n');
        } else if (c == '\r') {
            // Skip CR
            continue;
        } else {
            if (c == '\t') {
                // Convert tab to space
                c = ' ';
            }
            lb.append((byte) c);
        }
    }
    return lb;
}

