public static LinkedBuffer writeUTF8(final CharSequence str,final WriteSession session,final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("input string cannot be null");
    }

    int len = str.length();
    byte[] encoded = new byte[len * 3]; // _UTF8 checked char data
    int index = 0;
    for (int i = 0; i < len; i++) {
        char ch = str.charAt(i);
        int c = (int) ch;
        if (c < 0x80) {
            encoded[index++] = (byte) c;
        } else if (c < 0x800) {
            encoded[index++] = (byte) (0xc0 | (c >> 6));
            encoded[index++] = (byte) (0x80 | (c & 0x3F));
        } else if (c < 0xD800 || c >= 0xE000) {
            encoded[index++] = (byte) (0xe0 | (c >> 12));
            encoded[index++] = (byte) (0x80 | ((c >> 6) & 0x3F));
            encoded[index++] = (byte) (0x80 | (c & 0x3F));
        } else {
            int next = str.charAt(i + 1);
            if ((next & 0xC0) != 0x80) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
            int codePoint = c | (next << 12);
            --index; // Back up one character
            encoded[index] = (byte) (0xf0 | (codePoint >> 18));
            encoded[index - 1] = (byte) (0x80 | ((codePoint >> 12) & 0x3F));
            encoded[index - 2] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
            encoded[index - 3] = (byte) (0x80 | (codePoint & 0x3F));
            i++; // Skip the next character
        }
    }

    lb.reset();
    for (int k = 0; k < index; k++) {
        lb.append(encoded[k]);
    }
    session.inc Updated(false);
    return lb;
}

