                throw new IllegalArgumentException("Invalid UTF-8 sequence encountered");
            }
        } else if (b < 0xe0) {
            if (i + 2 >= str.length()) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence encountered");
            }
            byte c = (byte) str.charAt(i + 1);
            byte d = (byte) str.charAt(i + 2);
            if (c < 0x80 && d < 0x80) {
                lb.writeChar(getString((char) b, (char) c, (char) d));
                i += 2;
            } else {
