public long readRawVarint64() throws IOException {
    long value = 0;
    int bitPos = 0;
    int b;

    int r = read(1);
    if (r == -1)
        throw new EOFException("EOF in mid-frame, pos = 0");

    do {
        value |= ((b & 0x7F) << bitPos);
        bitPos += 7;
        if (bitPos == 64)
            throw new IOException("VarInt64 too large");

        r = read(1);
        if (r == -1) {
            throw new EOFException("EOF in mid-frame, pos = " + bitPos);
        }
        b = r & 0xFF;
    } while ((b & 0x80) != 0);

    return value;
}

