public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    out.writeInt(node.getCapacity());  // Write the capacity
    out.writeInt(node.fullSize());  // Write the full size
    out.writeInt(node.size());  // Write the size
    out.writeInt(node.getReadableByteCount());  // Write the readable byte count
    out.writeByte(node.getOffset());
    out.writeByte(node.getDirection());  // Write the direction
    out.writeInt(node.getFirstBuffer().getLength());  // Write the length of the first buffer
    out.writeInt(node.getFirstBuffer().indexOfRange(0));  // Write the index of the first buffer range
    int index = 0;  // Counter for buffers
    while (index < node.getNumBuffers()) {
        out.writeInt(node.getBuffers()[index].getLength());  // Write the length of each buffer
        out.writeInt(node.getBuffers()[index].indexOfRange(0));  // Write the index of the buffer range
        index++;
    }
    return node.getCapacity();  // Return the total content size
}

public static int writeTo(final DataOutput out,LinkedBuffer node) throws IOException {
    int totalSize = 0;
    int blockSize = node.getBlockSize(); // Assuming a constant block size for simplicity
    byte[] buffer = node.getDataBuffer();
    for (int i = 0; i < blockSize; i++) {
        if (buffer[i] == null) {
            out.writeByte(0xFF); // Indicate null value
            totalSize++;
            continue;
        }
        out.writeByte(buffer[i]);
        totalSize++;
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    out.writeInt(node.getSize()); // Write size of the buffer
    out.writeBytes(node.getData()); // Write the data of the buffer
    return node.getSize() + node.getData().length; // Return the total content size
}

