public static int nextPrime(int desiredCapacity) {
    // Check if the desiredCapacity is less than 2
    if (desiredCapacity < 2) {
        return 2;
    }

    // Find the next smallest prime number greater than or equal to desiredCapacity
    int prime = desiredCapacity;
    while (!isPrime(prime)) {
        prime++;
    }

    return prime;
}

private static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 0) return 1;

    int prime = 2;
    while (true) {
        if (isPrime(prime)) {
            if (prime >= desiredCapacity) break;
        }
        prime += 1;
    }
    return prime;
}

public static int nextPrime(int desiredCapacity) {
    int result = desiredCapacity > 19 ? 37 : 7;

    while (true) {
        int candidate = result + 7;
        boolean isPrime = true;

        for (int i = 2; i * i <= candidate; i++) {
            if (candidate % i == 0) {
                isPrime = false;
                break;
            }
        }

        if (isPrime && candidate >= desiredCapacity) {
            return candidate;
        }

        result += 6;
    }
}

