        if (curr == '\\') {
            i++;
            if (i >= len) {
                throw new IllegalArgumentException("Unescaped character at end of string");
            }
            curr = str.charAt(i);
            if (curr == 't') {
                result.append('\t');
            } else if (curr == 'n') {
                result.append('\n');
            } else if (curr == 'r') {
                result.append('\r');
            } else if (curr == '\"') {
                result.append('"');
            } else if (curr == '\\') {
                result.append('\\');
            } else if (curr == 'x') {
                i++;
                if (i >= len) {
                    throw new IllegalArgumentException("Unescaped character at end of string");
                }
                int hex = Character.digit(str.charAt(i), 16) & 0xF;
                i++;
                if (i >= len) {
                    throw new IllegalArgumentException("Unescaped character at end of string");
                }
                hex = (hex << 4) + Character.digit(str.charAt(i), 16) & 0xF;
                result.append((char) hex);
            } else {
                throw new IllegalArgumentException("Unrecognized escape sequence: \\U" + Integer.toHexString(curr));
            }
        } else {
            result.append(curr);
        }
    }
    return result.toString();
}

