public static <T> T[] copyArrayGrow1(final T[] array, final Class<T> newArrayComponentType) {
    // validate the input array
    if (array == null) {
        throw new IllegalArgumentException("Input array 'array' cannot be null");
    }

    // get the size of the original array
    int length = array.length;

    // create a new array with size 1 greater than the original array
    T[] newArray = (T[]) Array.newInstance(newArrayComponentType, length + 1);

    // copy the original array elements to the new array
    for (int i = 0; i < length; i++) {
        newArray[i] = array[i];
    }

    // return the new array
    return newArray;
}

public Object copyArrayGrow1(final Object array,final Class<?> newArrayComponentType) {
    if (array == null) {
        int length = (newArrayComponentType == null) ? 1 : Array.getLength(array);
        return Array.newInstance(newArrayComponentType, length + 1);
    } else {
        int length = Array.getLength(array) + 1;
        Object copy = Array.newInstance(newArrayComponentType, length);
        System.arraycopy(array, 0, copy, 0, length - 1);
        return copy;
    }
}

