private String unescapeId(String input) {
    StringBuilder sb = new StringBuilder();
    int len = input.length();
    for (int i = 0; i < len; i++) {
        char ch = input.charAt(i);
        switch (ch) {
            case '<':
                if (i + 1 < len && input.charAt(i + 1) == '>') {
                    sb.append('>');
                    i++;
                } else {
                    sb.append('<');
                }
                break;
            case '>':
                if (i + 1 < len && input.charAt(i + 1) == '<') {
                    sb.append('<');
                    i++;
                } else {
                    sb.append('>');
                }
                break;
            case '\"':
                sb.append("\\\"");
                break;
            case '\\':
                if (i + 1 < len && input.charAt(i + 1) == '\"') {
                    sb.append("\\\"");
                    i++;
                } else {
                    sb.append("\\");
                }
                break;
            default:
                sb.append(ch);
        }
    }
    return sb.toString();
}

