    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            i++;
            char esc = input.charAt(i);
            switch (esc) {
                case 'n':
                    sb.append('\n');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 'u':
                    i++;
                    int hexValue = Integer.parseInt(input.substring(i, i + 4), 16);
                    sb.append((char) hexValue);
                    i += 3;
                    break;
                default:
                    sb.append('\\');
                    sb.append(esc);
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

