    int length = input.length();
    StringBuilder result = new StringBuilder(length / 2);
    for (int i = 0; i < length; i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            c = input.charAt(i + 1);
            if (c == 'n') {
                result.append('\n');
            } else if (c == 't') {
                result.append('\t');
            } else if (c == 'r') {
                result.append('\r');
            } else if (c == 'b') {
                result.append('\b');
            } else if (c == '\\' || c == '"') {
                result.append(c);
            } else {
                throw new IllegalArgumentException("Invalid escape sequence at position " + i);
            }
            i++; // Skip the following character as it's part of the escape sequence
