        throw new IllegalArgumentException("Invalid input: labels should not be null or minLabel should be non-negative");
    }

    // Remove all vertices with labels less than minLabel
    for (int i = minLabel; i < labels.size(); i++) {
        List<Integer> verticesFromMin = bucketsByLabel.get(i);
        if (!verticesFromMin.isEmpty()) {
            bucketsByLabel.remove(i);
            labels.remove(i);
        }
    }

    // Move all vertices from the bucket with label minLabel to the bucket with label 0
    if (!labels.isEmpty()) {
        List<Integer> verticesFromMin = bucketsByLabel.get(minLabel);
        List<Integer> verticesToZero = bucketsByLabel.get(0);
        if (!verticesToZero.isEmpty()) {
            verticesToZero.addAll(verticesFromMin);
            verticesFromMin.clear();
        } else {
            bucketsByLabel.add(0, verticesFromMin);
        }
    }
}

