    while (inputOffset < input.length() && input.charAt(inputOffset) != '\n' && !Arrays.stream(terminators).anyMatch(c -> c == currentChar)) {
        token.append(currentChar);
        inputOffset++;
        currentChar = input.charAt(inputOffset);
    }
    return token.toString();
}

