public String parseToken(final char[] terminators) {
    StringBuffer tokenBuffer = new StringBuffer();
    boolean inToken = false;

    for (char c : this.toCharArray()) {
        if (inToken) {
            if (Arrays.binarySearch(terminators, c) >= 0) {
                break;
            }
            tokenBuffer.append(c);
        } else {
            if (Arrays.binarySearch(terminators, c) >= 0) {
                inToken = true;
                tokenBuffer.append(c);
            }
        }
    }

    return tokenBuffer.toString();
}

private String parseToken(final char[] terminators) {
    char c;
    StringBuilder sb = new StringBuilder();
    do {
        c = (char) System.in.read(); // Read character from input stream
        if (Arrays.stream(terminators).anyMatch(ch -> ch == c)) {
            break;
        }
        sb.append(c);
    } while (true);
    return sb.toString();
}

