private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Implement the logic to check if the given vertices form a clique in the graph
    // If the set of vertices is not of the same size as the graph, return false immediately
    if (vertices.size() != graph.vertexSet().size()) {
        return false;
    }

    // Iterate through each vertex in the vertices set
    for (V vertex : vertices) {
        // Check if all other vertices in the vertices set are adjacents to the current vertex
        for (V otherVertex : vertices) {
            // If the other vertex is not adjacent to the current vertex, return false
            if (!graph.hasEdge(vertex, otherVertex)) {
                return false;
            }
        }
    }

    // If all checks pass, the vertices form a clique
    return true;
}

