    for (V vertex : vertices) {
        if (!graph.containsVertex(vertex)) {
            return false;
        }
        Set<Edge<V, E>> associatedEdges = graph.edgesOf(vertex);
        if (associatedEdges.size() != vertices.size() - 1) {
            return false;
        }
    }
    return true;
}

