private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    for (V vertex1 : vertices) {
        Set<E> neighbors1 = graph.neighbors(vertex1);
        if (neighbors1.size() < vertices.size() - 1) {
            return false;
        }
        for (V vertex2 : vertices) {
            if (vertex1 == vertex2) {
                continue;
            }
            Set<E> neighbors2 = graph.neighbors(vertex2);
            if (!neighbors1.containsAll(neighbors2)) {
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Start by assuming the subgraph is a clique
    boolean isClique = true;

    // For each pair of vertices in the subgraph
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1 != v2 && !graph.containsEdge(v1, v2)) {
                // Check if there is no edge between the vertices
                isClique = false;
                break;
            }
        }
        if (!isClique) break;
    }

    return isClique;
}

