public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null || path.isEmpty() || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Path and relative path cannot be null or empty.");
    }

    StringBuilder sb = new StringBuilder();
    int index = 0;

    while (index < relativePath.length()) {
        if (index <= relativePath.length() - 2 && relativePath.charAt(index) == '.' && relativePath.charAt(index + 1) == '.') {
            index += 2; // Skip two dots
            continue;
        } else if (relativePath.charAt(index) == '.') {
            index++; // Skip dot
            if (index >= relativePath.length()) {
                // If there are no more characters, append the remainder of the relative path to the path parts
                sb.append(relativePath.substring(index));
                break;
            }
            char nextChar = relativePath.charAt(index);
            if (nextChar == '/') {
                // Join the current part with the next part separated by a slash
                sb.append(path.substring(index - 1));
                sb.append("/");
                index++; // Skip the current character
            } else {
                int start = index;
                while (index < relativePath.length() && !Character.isSeparator(relativePath.charAt(index))) {
                    index++;
                }
                sb.append(relativePath.substring(start, index));
                index++; // Skip the current character
            }
        } else {
            sb.append(relativePath.charAt(index));
            index++;
        }
    }

    if (index == relativePath.length()) {
        // If the relative path ends with a slash, append the path's final part
        sb.append(path);
    }

    return sb.toString();
}

