    byte[] buffer = new byte[1024];
    int position = 0;

    // read bytes until EOF or break
    while (true) {
        int bytesRead = fileChannel.read(ByteBuffer.wrap(buffer, position, buffer.length - position));
        if (bytesRead <= 0) break; // read nothing or EOF

        // process byte buffer
        for (int i = 0; i < bytesRead; i++) {
            int byteValue = buffer[position + i];
            if (byteValue == 0) break; // found EOF or zero tag
            // process the byte value appropriately
        }

        position += bytesRead;
    }

    return 0; // return zero as per requirement
}

